{
  "steps": [
    {
      "id": "s1",
      "description": "Use list_documents to identify all available project documents, then read_document to examine candidate_specs.md to identify the three candidate absorber materials and their relevant properties, especially residual dose rate information."
    },
    {
      "id": "s2",
      "description": "Review the residual dose rate constraint (20 uSv/h at 1 m after one week cooldown) against the candidate materials from candidate_specs.md to eliminate any materials that cannot meet this hard requirement, regardless of their energy resolution performance."
    },
    {
      "id": "s3",
      "description": "For each material that passes the dose rate constraint, run simulate_resolution with a mid-range plate thickness (e.g., 5-6 mm) to get initial energy resolution baselines and identify the most promising candidate(s)."
    },
    {
      "id": "s4",
      "description": "For the most promising material(s) from s3, run simulate_resolution at multiple plate thicknesses within the 2-10 mm range (e.g., 2, 4, 6, 8, 10 mm) to map the energy resolution as a function of thickness."
    },
    {
      "id": "s5",
      "description": "Use record_results to compile all simulation results, dose rate evaluations, and identify the optimal combination of material and plate thickness that achieves the best energy resolution while satisfying the dose rate constraint."
    }
  ]
}
